import{_ as a,a as r,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"小学四年级数学：知识讲解 · 数对、方格位置与平移至植树间隔与周期规律","description":"小学四年级数学 20 个知识点，包含定义、方法、例题、易错与本地图示。","frontmatter":{"title":"小学四年级数学：知识讲解 · 数对、方格位置与平移至植树间隔与周期规律","description":"小学四年级数学 20 个知识点，包含定义、方法、例题、易错与本地图示。","splitFrom":"life/math/primary/grade-4/knowledge.md","showdocs":{"topics":[{"id":"math","title":"数学","link":"/topics/math/"}],"kind":"知识讲解","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"小学四年级数学：知识讲解","summary":"小学四年级数学 20 个知识点，包含定义、方法、例题、易错与本地图示。","status":"active","related":[{"title":"八年级数学独立习题集","link":"/life/math/junior/grade-8/exercises","kind":"习题与解析","scope":"general","audience":"general"},{"title":"八年级数学独立习题集 · 平方根、立方根与实数至一次函数与实际方案比较","link":"/life/math/junior/grade-8/exercises-part-01","kind":"习题与解析","scope":"general","audience":"general"},{"title":"八年级数学独立习题集 · 三角形全等与对应关系至加权平均数与方差","link":"/life/math/junior/grade-8/exercises-part-02","kind":"习题与解析","scope":"general","audience":"general"},{"title":"八年级数学公式速查","link":"/life/math/junior/grade-8/formulas","kind":"公式与参考","scope":"general","audience":"general"},{"title":"程序员数学 11：文件处理任务的数学复盘","link":"/life/math/programmer/practice","kind":"习题与解析","scope":"general","audience":"general"}],"prev":{"text":"小学四年级数学：知识讲解 · 大数、数级与十进制至平行四边形、梯形与高","link":"/life/math/primary/grade-4/knowledge-part-01"},"next":{"text":"小学四年级数学：公式与规则速查","link":"/life/math/primary/grade-4/formulas"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"小学四年级数学：知识讲解 · 大数、数级与十进制至平行四边形、梯形与高","link":"/life/math/primary/grade-4/knowledge-part-01"},"next":{"text":"小学四年级数学：公式与规则速查","link":"/life/math/primary/grade-4/formulas"}},"headers":[],"relativePath":"life/math/primary/grade-4/knowledge-part-02.md","filePath":"life/math/primary/grade-4/knowledge-part-02.md"}'),p={name:"life/math/primary/grade-4/knowledge-part-02.md"};function n(o,e,s,l,g,d){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="小学四年级数学-知识讲解-·-数对、方格位置与平移至植树间隔与周期规律" tabindex="-1">小学四年级数学：知识讲解 · 数对、方格位置与平移至植树间隔与周期规律 <a class="header-anchor" href="#小学四年级数学-知识讲解-·-数对、方格位置与平移至植树间隔与周期规律" aria-label="Permalink to &quot;小学四年级数学：知识讲解 · 数对、方格位置与平移至植树间隔与周期规律&quot;">​</a></h1><p><a href="/life/math/primary/grade-4/knowledge">返回分篇目录</a></p><p><a href="/life/math/primary/grade-4/knowledge">知识讲解</a> · <a href="/life/math/primary/grade-4/formulas">公式速查</a> · <a href="/life/math/primary/grade-4/exercises">独立习题集</a></p><p>按六三三学段编排的通用建议学习顺序；不同地区、教材和学期安排存在差异。本版覆盖以下明确列出的知识点，不将其等同于所有教材或完整课程标准。</p><h2 id="p4-16" tabindex="-1">数对、方格位置与平移 <a class="header-anchor" href="#p4-16" aria-label="Permalink to &quot;数对、方格位置与平移 {#p4-16}&quot;">​</a></h2><p><strong>定义与条件：</strong> 在约定“先列后行”的方格图中，用数对表示位置。平移时每个点都沿同一方向移动同样距离，图形大小形状不变。</p><p><strong>方法：</strong> 先读列号，再读行号；若列向右增加、行向上增加，右移增加列号，上移增加行号。</p><p><strong>例子：</strong> 点 A 在第 2 列第 3 行，记为 (2,3)；向右移 4 格后变为 (6,3)。</p><p><strong>易错：</strong> 数对次序不能互换；地图的向上与行号增减须按题目约定。</p><p><a href="/life/math/primary/grade-4/formulas#p4-16">对应公式</a> · <a href="/life/math/primary/grade-4/exercises#p4-16">练习题组</a></p><h2 id="p4-17" tabindex="-1">平均数与移多补少 <a class="header-anchor" href="#p4-17" aria-label="Permalink to &quot;平均数与移多补少 {#p4-17}&quot;">​</a></h2><p><strong>定义与条件：</strong> 平均数是总量按份数均分的结果，用来描述一组数据的总体水平。每个数据不必等于平均数。</p><p><strong>方法：</strong> 求和后除以数据个数；也可用移多补少理解。合并两组时，若人数不同，不能直接平均两个平均数。</p><p><strong>例子：</strong> 三人读书 8、10、12 本，平均为 (8＋10＋12)÷3＝10 本；可以把 12 中的 2 移给 8。</p><p><strong>易错：</strong> 平均数可能不是原数据中的某一个值；多个平均数平均前需考虑各组份数。</p><p><a href="/life/math/primary/grade-4/formulas#p4-17">对应公式</a> · <a href="/life/math/primary/grade-4/exercises#p4-17">练习题组</a></p><h2 id="p4-18" tabindex="-1">条形统计图与刻度 <a class="header-anchor" href="#p4-18" aria-label="Permalink to &quot;条形统计图与刻度 {#p4-18}&quot;">​</a></h2><p><strong>定义与条件：</strong> 条形统计图用直条长度表示数量，便于比较类别多少。横轴、纵轴、图例与刻度单位共同决定图的含义。</p><p><strong>方法：</strong> 读图前看一格代表多少；根据数量确定条高，比较时应以同一尺度为准。</p><p><strong>例子：</strong> 每格表示 5 人，一根条高 6 格表示 30 人；两条相差 2 格表示相差 10 人。</p><p><strong>易错：</strong> 图的视觉差距受刻度影响，不能不看刻度就判断实际差。</p><p><a href="/life/math/primary/grade-4/formulas#p4-18">对应公式</a> · <a href="/life/math/primary/grade-4/exercises#p4-18">练习题组</a></p><h2 id="p4-19" tabindex="-1">统筹安排与最优顺序 <a class="header-anchor" href="#p4-19" aria-label="Permalink to &quot;统筹安排与最优顺序 {#p4-19}&quot;">​</a></h2><p><strong>定义与条件：</strong> 多项任务若能同时进行，可以减少总用时；不能并行的步骤必须按先后顺序完成。比较方案时应列出资源和依赖关系。</p><p><strong>方法：</strong> 先画时间线，把不占用同一资源且无先后冲突的任务重叠安排，再计算关键步骤结束时间。</p><p><strong>例子：</strong> 烧水 8 分钟时，可同时用 3 分钟洗杯子、2 分钟放茶叶；若放茶叶须在洗杯后完成，这两步共 5 分钟仍能放在烧水的 8 分钟内。</p><p><strong>易错：</strong> 并非所有时长都能直接取最大值；只有可以同时开始、互不冲突的任务才允许重叠。</p><p><a href="/life/math/primary/grade-4/formulas#p4-19">对应公式</a> · <a href="/life/math/primary/grade-4/exercises#p4-19">练习题组</a></p><h2 id="p4-20" tabindex="-1">植树间隔与周期规律 <a class="header-anchor" href="#p4-20" aria-label="Permalink to &quot;植树间隔与周期规律 {#p4-20}&quot;">​</a></h2><p><strong>定义与条件：</strong> 等距排列中，物体数与间隔数取决于是否包含两端、是否闭合；周期问题通过完整周期与余数定位。</p><p><strong>方法：</strong> 先画少量点检查“点数与段数”的关系；周期先找一个完整重复单元，再用除法确定所处位置。</p><p><strong>例子：</strong> 一条长 30 米的小路，每 5 米种一棵，两端都种，有 30÷5＝6 段、7 棵；圆周同样分 6 段则种 6 棵。</p><p><strong>易错：</strong> 直线两端都种、只种一端、两端不种、闭合路线不能套同一个数。</p><p><a href="/life/math/primary/grade-4/formulas#p4-20">对应公式</a> · <a href="/life/math/primary/grade-4/exercises#p4-20">练习题组</a></p>',34)])])}const f=a(p,[["render",n]]);export{h as __pageData,f as default};
